// LRU 缓存实现（哈希表 + 双向链表），用于说明精确 LRU 为什么适合缓存题、不适合 OS 每次访存路径
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int key, value;
    struct Node *prev, *next;
} Node;

typedef struct {
    int capacity, size;
    Node *head, *tail;
    // 简化：用数组模拟哈希表，真实系统需要处理 key 范围和哈希冲突
    Node *hash[10000];
} LRUCache;

LRUCache* createCache(int capacity) {
    LRUCache *cache = malloc(sizeof(LRUCache));
    cache->capacity = capacity;
    cache->size = 0;
    cache->head = malloc(sizeof(Node));
    cache->tail = malloc(sizeof(Node));
    cache->head->next = cache->tail;
    cache->tail->prev = cache->head;
    memset(cache->hash, 0, sizeof(cache->hash));
    return cache;
}

// 访问页面：命中时移动到链表头部，表示最近使用
void accessPage(LRUCache *cache, int key) {
    Node *node = cache->hash[key];
    if (node) {
        // 已存在：从原位置摘下，再插入头部
        node->prev->next = node->next;
        node->next->prev = node->prev;
        node->next = cache->head->next;
        node->prev = cache->head;
        cache->head->next->prev = node;
        cache->head->next = node;
    } else {
        // 新页面：容量满时淘汰尾部的最久未使用节点
        if (cache->size >= cache->capacity) {
            Node *old = cache->tail->prev;
            old->prev->next = cache->tail;
            cache->tail->prev = old->prev;
            cache->hash[old->key] = NULL;
            free(old);
            cache->size--;
        }
        // 插入新节点到头部，表示刚刚被访问
        node = malloc(sizeof(Node));
        node->key = key;
        node->next = cache->head->next;
        node->prev = cache->head;
        cache->head->next->prev = node;
        cache->head->next = node;
        cache->hash[key] = node;
        cache->size++;
    }
}
